def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [m for m, o in history]
    opp = [o for m, o in history]
    last_opp = opp[-1]
    last_my = my[-1]
    if n == 1:
        return 'C' if last_opp == 'C' else 'D'
    for i in range(1, n):
        if my[i] == 'C' and opp[i] == 'D' and opp[i-1] == 'D':
            return 'D'
    reactive = False
    for i in range(n - 1):
        if my[i] == 'D' and opp[i + 1] == 'D':
            reactive = True
            break
    my_C = 0
    opp_D = 0
    opp_D_when_my_C = 0
    for i in range(n):
        if my[i] == 'C':
            my_C += 1
            if opp[i] == 'D':
                opp_D_when_my_C += 1
        if opp[i] == 'D':
            opp_D += 1
    rate_opp_D_my_C = opp_D_when_my_C / my_C if my_C > 0 else 0.0
    if my_C >= 5 and rate_opp_D_my_C > 0.35:
        return 'D'
    if opp_D > n * 0.5:
        return 'D'
    if reactive:
        return 'C'
    if last_opp == 'D':
        return 'D'
    if n < 90 and n % 10 == 0 and rate_opp_D_my_C < 0.2:
        return 'D'
    return 'C'
